@layer hj.components {
  /* Customise: --hj-spinner-size · --hj-spinner-stroke · --hj-spinner-color */
  .hj-spinner {
    --_s: var(--hj-spinner-size, 20px);
    --_w: var(--hj-spinner-stroke, 2px);
    position: relative;
    display: inline-block;
    flex: none;
    width: var(--_s);
    height: var(--_s);
    color: var(--hj-spinner-color, var(--hj-accent));
    vertical-align: middle;
    animation: hj-fade-in var(--hj-dur-base) var(--hj-ease-out) both;
  }
  .hj-spinner[data-size='sm'] {
    --_s: var(--hj-spinner-size, 16px);
  }
  .hj-spinner[data-size='lg'] {
    --_s: var(--hj-spinner-size, 40px);
    --_w: var(--hj-spinner-stroke, 3px);
  }
  .hj-spinner[data-tone='current'] {
    color: var(--hj-spinner-color, currentColor);
  }
  .hj-spinner[data-waiting] {
    visibility: hidden;
    animation: none;
  }

  /* The ring turns on its own element, so containers can scale the spinner freely. */
  .hj-spinner-ring {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    animation: var(--hj-anim-spin);
  }
  .hj-spinner-ring::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 50%;
    background: conic-gradient(from 0deg, transparent 0deg 40deg, currentColor 360deg);
    mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--_w) - 0.5px),
      black calc(100% - var(--_w))
    );
  }
  .hj-spinner-ring::after {
    content: '';
    position: absolute;
    top: 0;
    left: calc(50% - var(--_w) / 2);
    width: var(--_w);
    height: var(--_w);
    border-radius: 50%;
    background: currentColor;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

/** Props hanji adds to the spinner. */
export interface SpinnerOwnProps {
  /** sm 16 (inline) · md 20 (buttons) · lg 40 (a page or a panel). */
  size?: 'sm' | 'md' | 'lg';
  /** accent, or `current` to take the surrounding text colour (inside buttons). */
  tone?: 'accent' | 'current';
  /**
   * Wait before appearing, so fast work never flashes a ring. `true` = 400 ms, or a number of ms.
   * @default false
   */
  delay?: boolean | number;
  /** Accessible name. Defaults to the provider's `strings.loading`. */
  label?: string;
  render?: useRender.RenderProp;
}

export interface SpinnerProps
  extends SpinnerOwnProps, Omit<React.ComponentProps<'span'>, 'className' | 'children'> {
  className?: string;
}

const DEFAULT_DELAY = 400;

/**
 * The ink ring: a constant turn, a tail that fades behind a round head. Feedback, not
 * decoration — under reduced motion it pulses in place instead of turning.
 *
 * @example
 * <Spinner delay /> {/* appears only if the wait passes 400 ms *\/}
 */
export function Spinner(props: SpinnerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    size = 'md',
    tone = 'accent',
    delay = false,
    label,
    render,
    className,
    ...rest
  } = withDefaults(config, 'Spinner', props);
  const wait = delay === true ? DEFAULT_DELAY : typeof delay === 'number' ? delay : 0;
  const [shown, setShown] = React.useState(wait === 0);
  React.useEffect(() => {
    if (wait === 0) return undefined;
    const t = window.setTimeout(() => setShown(true), wait);
    return () => window.clearTimeout(t);
  }, [wait]);

  return useRender({
    render,
    defaultTagName: 'span',
    props: {
      role: shown ? 'progressbar' : undefined,
      'aria-label': shown ? (label ?? config.strings.loading) : undefined,
      'aria-hidden': shown ? undefined : true,
      ...rest,
      'data-size': size,
      'data-tone': tone,
      'data-waiting': flag(!shown),
      className: cls(config, 'Spinner', 'hj-spinner', className) as string | undefined,
      children: <span className={config.unstyled ? undefined : 'hj-spinner-ring'} />,
    },
  });
}
